  const startMs = new Date(team.inicio).getTime();
  const elapsedSec = Number.isFinite(startMs) ? Math.floor((Date.now() - startMs) / 1000) : 0;
  const fmtEstado = s => `${Math.floor(s / 60)} min ${s % 60} s`;
  const pasoActual = Math.min(pasoDe(team), 8);
  response = `📜 ESTADO DEL EQUIPO\n\nEquipo: ${team.nombre}\nEnclave: ${pasoActual} de 8\n⏱ Tiempo transcurrido: ${fmtEstado(elapsedSec)}\nFragmentos del Códice: "${fragmentosHasta(station, pasoActual - 1)}"\nPistas: ${team.pistas_usadas}\nMapas: ${team.mapas_usados}\nPenalización: ${team.penalizacion_minutos} min`;
} else if (msg.text === 'repetir' || msg.text === '/repetir') {
  if (!team.acertijo_visto) {
    team.acertijo_visto = true;
    changed = true;
  }
  response = `📍 Enclave ${station.orden}: ${station.nombre}\n\n🧩 ${station.acertijo}`;
  imagenUrl = station.imagen_url || '';
} else {
  const accepted = String(station.respuestas || '').split('|').map(norm);
  if (accepted.includes(msg.text)) {
    if (Number(team.estacion_actual) >= 9) {
      team.estado = 'finalizado';
      team.fin = now;
      const startMs = new Date(team.inicio).getTime();
      const elapsed = Number.isFinite(startMs) ? Math.floor((Date.now()-startMs)/1000) : 0;
      response = construirMensajeFinal(team, elapsed);
      imagenUrl = station.imagen_final_url || station.imagen_url || '';
      documentoUrl = station.guia_historica_url || '';
    } else {
      const paso = pasoDe(team);
      const ordenInicio = ordenInicioDe(team);
      const nuevoPaso = paso + 1;
      team.orden_inicio = ordenInicio;
      team.paso = nuevoPaso;
      team.estacion_actual = estacionFisica(ordenInicio, nuevoPaso);
      team.pista_actual = 0;
      team.acertijo_visto = false;
      capsulaMsg = `✅ ¡Respuesta correcta!\n\n${station.capsula}`;
      response = `Fragmentos del Códice: "${fragmentosHasta(station, paso)}"`;
      siguienteEstacionId = String(team.estacion_actual);
    }
    changed = true;
  } else {
    team.intentos = Number(team.intentos || 0) + 1;
    changed = true;
    response = '❌ Esa respuesta no es correcta. Observad de nuevo o escribid PISTA.';
  }
}

team.actualizado_en = now;
return [{json:{...team,response,chat_id:msg.chat_id,changed,imagen_url:imagenUrl,capsula_msg:capsulaMsg,documento_url:documentoUrl,siguiente_estacion_id:siguienteEstacionId}}];

const prev = $('Procesar estación y comandos').first().json;
const next = $json;

function fragmentosHasta(station, n) {
  const partes = [];
  for (let i = 1; i <= n; i++) {
    const v = station['paso' + i + '_fragmento'];
    if (v) partes.push(v);
  }
  return partes.join(' ');
}

let siguienteTexto;

if (String(next.id) === '9') {
  siguienteTexto = `🧩 *¡EL CÓDICE ESTÁ COMPLETO!*

Al unir los ocho fragmentos obtenemos unas coordenadas...
👉 \`${next.coordenadas_finales}\`

📍 Dirigíos hasta ese punto para realizar la última misión.

🚶 *Última misión:*
1️⃣ Dirigíos hacia el enclave secreto: *${next.nombre}*.
2️⃣ 🗺️ Mapa: ${next.mapa_url}

📍 Al llegar, escribid \`/destino\` para afrontar el desenlace.`;
} else {
  siguienteTexto = `➡️ *Próximo enclave:* ${next.nombre}
🗺️ Mapa: ${next.mapa_url}

📍 Al llegar, escribid \`/destino\`.`;
}

const response = `${prev.response}\n\n${siguienteTexto}`;
return [{ json: { ...prev, response } }];
